            }
            ScatterKind::Tent => {
                commands.spawn((Name::new("Tent"), Mesh3d(tent_m.clone()), MeshMaterial3d(tent.clone()), tf * Transform::from_xyz(0.0, 1.0, 0.0).with_rotation(Quat::from_rotation_y(std::f32::consts::FRAC_PI_4))));
            }
            ScatterKind::Campfire => {
                commands.spawn((Name::new("Campfire"), Mesh3d(fire_m.clone()), MeshMaterial3d(fire.clone()), tf * Transform::from_xyz(0.0, 0.3, 0.0))).with_children(|c| {
                    c.spawn((
