    let fire = mats.add(StandardMaterial { base_color: Color::srgb(1.0, 0.45, 0.1), emissive: LinearRgba::rgb(40.0, 14.0, 2.0), ..default() });

    let trunk_m = meshes.add(Cylinder::new(0.22, 2.0));
    let cone_m = meshes.add(Cone::new(1.6, 3.4));
    let cone2_m = meshes.add(Cone::new(1.15, 3.0));
    let rock_m = meshes.add(Sphere::new(1.0).mesh().ico(2).unwrap());
    let grass_m = meshes.add(Cone::new(0.18, 0.7));
    let reed_m = meshes.add(Cylinder::new(0.03, 1.8));
    let plank_m = meshes.add(Cuboid::new(2.6, 0.12, 0.9));
    let log_m = meshes.add(Cylinder::new(0.25, 1.8));
    let tent_m = meshes.add(Cone::new(1.9, 2.0).mesh().resolution(4));
    let fire_m = meshes.add(Sphere::new(0.28));

    for it in generate_scatter_plan(spec, grid) {
        let tf = Transform { translation: it.pos, rotation: it.rot, scale: Vec3::splat(it.scale) };
        match it.kind {
            ScatterKind::Pine => {
                commands.spawn((Name::new("Pine"), tf, Visibility::default())).with_children(|c| {
                    c.spawn((Mesh3d(trunk_m.clone()), MeshMaterial3d(bark.clone()), Transform::from_xyz(0.0, 1.0, 0.0)));
                    c.spawn((Mesh3d(cone_m.clone()), MeshMaterial3d(needles.clone()), Transform::from_xyz(0.0, 3.2, 0.0)));
                    c.spawn((Mesh3d(cone2_m.clone()), MeshMaterial3d(needles2.clone()), Transform::from_xyz(0.0, 5.3, 0.0)));
                });
            }
            ScatterKind::Boulder => {
                commands.spawn((Name::new("Boulder"), Mesh3d(rock_m.clone()), MeshMaterial3d(rock.clone()), tf.with_scale(Vec3::new(1.2, 0.8, 1.0) * it.scale)));
            }
            ScatterKind::Grass => {
                commands.spawn((Mesh3d(grass_m.clone()), MeshMaterial3d(grass.clone()), tf * Transform::from_xyz(0.0, 0.3, 0.0)));
            }
            ScatterKind::Reed => {
                commands.spawn((Mesh3d(reed_m.clone()), MeshMaterial3d(reed.clone()), tf * Transform::from_xyz(0.0, 0.8, 0.0)));
            }
            ScatterKind::PierPlank => {
                commands.spawn((Name::new("PierPlank"), Mesh3d(plank_m.clone()), MeshMaterial3d(wood.clone()), tf));
            }
            ScatterKind::Log => {
                commands.spawn((
                    Name::new("Log"),
                    Mesh3d(log_m.clone()),
                    MeshMaterial3d(wood.clone()),
                    tf * Transform::from_xyz(0.0, 0.25, 0.0).with_rotation(Quat::from_rotation_z(std::f32::consts::FRAC_PI_2)),
                ));
            }
            ScatterKind::Tent => {
                commands.spawn((
                    Name::new("Tent"),
                    Mesh3d(tent_m.clone()),
                    MeshMaterial3d(tent.clone()),
                    tf * Transform::from_xyz(0.0, 1.0, 0.0).with_rotation(Quat::from_rotation_y(std::f32::consts::FRAC_PI_4)),
                ));
            }
            ScatterKind::Campfire => {
